SELECT ?film ?filmLabel ?director ?directorLabel ?dob WHERE {
  VALUES ?film { dbr:Pobočník_Jeho_Výsosti dbr:Expertos_en_Pinchazos }
  ?film dbo:director ?director .
  OPTIONAL {
    { ?director dbo:birthDate ?dob } UNION
    { ?director dbp:birthDate ?dob } UNION
    { ?director dbp:born ?dob } UNION
    { ?director dbp:birth ?dob }
  }
  OPTIONAL { ?film rdfs:label ?filmLabel FILTER (langMatches(lang(?filmLabel),'en')) }
  OPTIONAL { ?director rdfs:label ?directorLabel FILTER (langMatches(lang(?directorLabel),'en')) }
}

